import React from "react";
import { AbsoluteFill, useCurrentFrame, interpolate, spring, Easing } from "remotion";
import { COLORS, FONTS, headlineGradient, ENGRAVE_SHADOW, PANEL_SHADOW, STYLE } from "../style-tokens";
import type { PrimitiveProps } from "../primitives";

type Item = { label: string; note?: string; done?: boolean };

const AlmostThereChecklist: React.FC<PrimitiveProps> = ({ anim, fps, dark, format, frame }) => {
  const f = useCurrentFrame();
  const S = frame.width / 1080;
  const p = (anim.params ?? {}) as Record<string, unknown>;

  const headline = String(p.headline ?? anim.text ?? "Almost everything");
  const eyebrow = String(p.eyebrow ?? "Checklist");
  const nextLabel = String(p.nextLabel ?? "Next");

  const rawItems = Array.isArray(p.items) ? (p.items as unknown[]) : [];
  const items: Item[] = rawItems.length
    ? rawItems.map((it) => {
        const o = (it ?? {}) as Record<string, unknown>;
        return {
          label: String(o.label ?? ""),
          note: o.note === undefined ? undefined : String(o.note),
          done: Boolean(o.done),
        };
      })
    : [
        { label: "Video clips", note: "Pexels", done: true },
        { label: "Background music", note: "Pixabay", done: true },
        { label: "The stories", note: "Last thing left", done: false },
      ];

  const txt = dark ? COLORS.textOnDark : COLORS.textOnLight;
  const muted = dark ? COLORS.mutedOnDark : COLORS.mutedOnLight;
  const radius = STYLE.sharp ? 0 : 22 * S;
  const clamp = (v: number) => Math.max(0, Math.min(1, v));

  const headIn = spring({ frame: f, fps, config: { damping: 16, mass: 0.6 } });
  const headSize = Math.min(
    frame.width * 0.115,
    (frame.width * 0.84) / Math.max(6, headline.length * 0.44)
  );

  const listW = frame.width * 0.8;
  const dotSize = 78 * S;

  return (
    <AbsoluteFill
      style={{
        fontFamily: FONTS.body,
        alignItems: "center",
        justifyContent: "center",
      }}
    >
      <div
        style={{
          width: listW,
          display: "flex",
          flexDirection: "column",
          alignItems: "flex-start",
          gap: 20 * S,
        }}
      >
        {/* eyebrow */}
        <div
          style={{
            opacity: clamp((f - 2) / 8),
            fontFamily: FONTS.body,
            fontWeight: 600,
            fontSize: 22 * S,
            letterSpacing: "0.24em",
            textTransform: "uppercase",
            color: muted,
          }}
        >
          {eyebrow}
        </div>

        {/* headline */}
        <div
          style={{
            opacity: clamp(f / 7),
            transform: `translateY(${interpolate(headIn, [0, 1], [34 * S, 0])}px)`,
            fontFamily: FONTS.display,
            fontWeight: FONTS.displayWeight,
            fontSize: headSize,
            lineHeight: 0.95,
            textTransform: "uppercase",
            wordBreak: "break-word",
            marginBottom: 12 * S,
            ...(STYLE.headline === "gradient"
              ? {
                  backgroundImage: headlineGradient(),
                  WebkitBackgroundClip: "text",
                  backgroundClip: "text",
                  color: "transparent",
                }
              : { color: COLORS.teal, textShadow: ENGRAVE_SHADOW }),
          }}
        >
          {headline}
        </div>

        {/* rows */}
        {items.map((it, i) => {
          const start = 8 + i * 9;
          const rowIn = spring({ frame: f - start, fps, config: { damping: 17, mass: 0.6 } });
          const rowO = clamp((f - start) / 8);
          const done = Boolean(it.done);
          const tick = clamp((f - (start + 6)) / 9);
          const focus = done ? 0 : interpolate(f, [42, 58], [0, 1], {
            extrapolateLeft: "clamp",
            extrapolateRight: "clamp",
            easing: Easing.out(Easing.cubic),
          });
          const breathe = done ? 1 : 1 + 0.015 * Math.sin((f - 46) / 5) * focus;

          const labelSize = Math.min(
            48 * S,
            (listW - dotSize - 40 * S) / Math.max(6, it.label.length * 0.5)
          );

          return (
            <div
              key={i}
              style={{
                width: "100%",
                boxSizing: "border-box",
                display: "flex",
                alignItems: "center",
                gap: 24 * S,
                padding: `${20 * S}px ${26 * S}px`,
                borderRadius: radius,
                background: done
                  ? "rgba(255,255,255,0.04)"
                  : `${COLORS.teal}1A`,
                border: done
                  ? `${Math.max(1, 1.5 * S)}px solid rgba(255,255,255,0.10)`
                  : `${Math.max(1, 2 * S)}px solid ${COLORS.teal}${focus > 0.5 ? "CC" : "66"}`,
                boxShadow: done ? undefined : PANEL_SHADOW,
                opacity: rowO * (done ? interpolate(focus, [0, 1], [1, 0.62]) : 1),
                transform: `translateX(${interpolate(rowIn, [0, 1], [-44 * S, 0])}px) scale(${breathe})`,
              }}
            >
              {/* marker */}
              <div
                style={{
                  width: dotSize,
                  height: dotSize,
                  flex: "0 0 auto",
                  borderRadius: STYLE.sharp ? 0 : 999,
                  display: "flex",
                  alignItems: "center",
                  justifyContent: "center",
                  background: done ? COLORS.teal : "transparent",
                  border: done
                    ? "none"
                    : `${Math.max(2, 3 * S)}px dashed ${COLORS.tealBright}`,
                  transform: done ? `scale(${0.7 + 0.3 * tick})` : `rotate(${f * 0.7}deg)`,
                }}
              >
                {done ? (
                  <svg
                    width={dotSize * 0.52}
                    height={dotSize * 0.52}
                    viewBox="0 0 24 24"
                    fill="none"
                  >
                    <path
                      d="M4 12.5 L10 18.5 L20 6"
                      stroke={COLORS.papyrus}
                      strokeWidth={3.2}
                      strokeLinecap="round"
                      strokeLinejoin="round"
                      strokeDasharray={30}
                      strokeDashoffset={30 * (1 - tick)}
                    />
                  </svg>
                ) : null}
              </div>

              {/* label block */}
              <div style={{ display: "flex", flexDirection: "column", gap: 6 * S, minWidth: 0 }}>
                <div
                  style={{
                    fontFamily: FONTS.display,
                    fontWeight: FONTS.displayWeight,
                    fontSize: labelSize,
                    lineHeight: 1.02,
                    textTransform: "uppercase",
                    color: done ? txt : COLORS.tealBright,
                    textDecoration: done ? "line-through" : "none",
                    textDecorationThickness: `${Math.max(2, 3 * S)}px`,
                    wordBreak: "break-word",
                  }}
                >
                  {it.label}
                </div>
                {it.note ? (
                  <div
                    style={{
                      fontFamily: FONTS.mono,
                      fontSize: 22 * S,
                      letterSpacing: "0.12em",
                      color: muted,
                      wordBreak: "break-word",
                    }}
                  >
                    {it.note}
                  </div>
                ) : null}
              </div>

              {/* next pill on the pending row */}
              {!done ? (
                <div
                  style={{
                    marginLeft: "auto",
                    flex: "0 0 auto",
                    opacity: focus,
                    transform: `scale(${0.8 + 0.2 * focus})`,
                    padding: `${10 * S}px ${20 * S}px`,
                    borderRadius: STYLE.sharp ? 0 : 999,
                    background: COLORS.teal,
                    color: COLORS.papyrus,
                    fontFamily: FONTS.body,
                    fontWeight: 700,
                    fontSize: 20 * S,
                    letterSpacing: "0.16em",
                    textTransform: "uppercase",
                    whiteSpace: "nowrap",
                  }}
                >
                  {nextLabel}
                </div>
              ) : null}
            </div>
          );
        })}
      </div>
    </AbsoluteFill>
  );
};

export default AlmostThereChecklist;
